package com.office.snacks.service;

import com.office.snacks.dto.ApiDtos.RecordRequest;
import com.office.snacks.entity.Employee;
import com.office.snacks.entity.Snack;
import com.office.snacks.entity.SnackRecord;
import com.office.snacks.repository.*;
import org.junit.jupiter.api.Test;
import org.springframework.test.util.ReflectionTestUtils;
import org.springframework.web.server.ResponseStatusException;
import java.util.Optional;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class SnackTrackerServiceTest {
 @Test void rejectsUnknownEmployee(){EmployeeRepository e=mock(EmployeeRepository.class);SnackRepository s=mock(SnackRepository.class);SnackRecordRepository r=mock(SnackRecordRepository.class);when(e.findById(99L)).thenReturn(Optional.empty());var service=new SnackTrackerService(e,s,r);assertThrows(ResponseStatusException.class,()->service.addRecord(new RecordRequest(99L,1L,1)));verifyNoInteractions(r);}
 @Test void rejectsUnknownSnack(){EmployeeRepository e=mock(EmployeeRepository.class);SnackRepository s=mock(SnackRepository.class);SnackRecordRepository r=mock(SnackRecordRepository.class);when(e.findById(1L)).thenReturn(Optional.of(new Employee("Mohan",true)));when(s.findById(77L)).thenReturn(Optional.empty());var service=new SnackTrackerService(e,s,r);assertThrows(ResponseStatusException.class,()->service.addRecord(new RecordRequest(1L,77L,1)));verifyNoInteractions(r);}
 @Test void rejectsInactiveEmployee(){EmployeeRepository e=mock(EmployeeRepository.class);when(e.findById(1L)).thenReturn(Optional.of(new Employee("Mohan",false)));var service=new SnackTrackerService(e,mock(SnackRepository.class),mock(SnackRecordRepository.class));assertThrows(ResponseStatusException.class,()->service.addRecord(new RecordRequest(1L,1L,1)));}
 @Test void rejectsNonPositiveQuantityBeforeRepositoryAccess(){EmployeeRepository e=mock(EmployeeRepository.class);SnackRepository s=mock(SnackRepository.class);SnackRecordRepository r=mock(SnackRecordRepository.class);var service=new SnackTrackerService(e,s,r);assertThrows(ResponseStatusException.class,()->service.addRecord(new RecordRequest(1L,1L,0)));verifyNoInteractions(e,s,r);}
 @Test void deactivatesEmployeeInsteadOfDeletingItsHistory(){Employee employee=new Employee("Mohan",true);EmployeeRepository e=mock(EmployeeRepository.class);SnackRecordRepository r=mock(SnackRecordRepository.class);when(e.findById(1L)).thenReturn(Optional.of(employee));when(r.existsByEmployee_Id(1L)).thenReturn(true);var service=new SnackTrackerService(e,mock(SnackRepository.class),r);var response=service.deleteEmployee(1L);assertFalse(response.deleted());assertFalse(employee.isActive());verify(e).save(employee);verify(e,never()).delete(any(Employee.class));}
 @Test void deactivatesSnackInsteadOfDeletingItsHistory(){Snack snack=new Snack("Tea",true);SnackRepository s=mock(SnackRepository.class);SnackRecordRepository r=mock(SnackRecordRepository.class);when(s.findById(1L)).thenReturn(Optional.of(snack));when(r.existsBySnack_Id(1L)).thenReturn(true);var service=new SnackTrackerService(mock(EmployeeRepository.class),s,r);var response=service.deleteSnack(1L);assertFalse(response.deleted());assertFalse(snack.isActive());verify(s).save(snack);verify(s,never()).delete(any(Snack.class));}
 @Test void employeeCannotEditAnotherEmployeesRecord(){EmployeeRepository e=mock(EmployeeRepository.class);SnackRepository s=mock(SnackRepository.class);SnackRecordRepository r=mock(SnackRecordRepository.class);Employee owner=new Employee("Other",true);ReflectionTestUtils.setField(owner,"id",2L);when(r.findDetailedById(5L)).thenReturn(Optional.of(new SnackRecord(owner,new Snack("Tea",true),1)));var service=new SnackTrackerService(e,s,r);assertThrows(ResponseStatusException.class,()->service.updateRecord(5L,new RecordRequest(1L,1L,2),1L));verifyNoInteractions(e,s);}
 @Test void adminCanUpdateSnackAndQuantity(){EmployeeRepository e=mock(EmployeeRepository.class);SnackRepository s=mock(SnackRepository.class);SnackRecordRepository r=mock(SnackRecordRepository.class);Employee employee=new Employee("Mohan",true);Snack oldSnack=new Snack("Tea",true),newSnack=new Snack("Coffee",true);SnackRecord existing=new SnackRecord(employee,oldSnack,1);when(r.findDetailedById(5L)).thenReturn(Optional.of(existing));when(e.findById(1L)).thenReturn(Optional.of(employee));when(s.findById(2L)).thenReturn(Optional.of(newSnack));when(r.save(existing)).thenReturn(existing);var service=new SnackTrackerService(e,s,r);var updated=service.updateRecord(5L,new RecordRequest(1L,2L,3),null);assertEquals("Coffee",updated.snackName());assertEquals(3,updated.quantity());}
 @Test void adminCanDeleteSnackRecord(){SnackRecordRepository r=mock(SnackRecordRepository.class);SnackRecord record=new SnackRecord(new Employee("Mohan",true),new Snack("Tea",true),1);when(r.findDetailedById(5L)).thenReturn(Optional.of(record));var service=new SnackTrackerService(mock(EmployeeRepository.class),mock(SnackRepository.class),r);service.deleteRecord(5L,null);verify(r).delete(record);}
 @Test void employeeCannotDeleteAnotherEmployeesSnackRecord(){SnackRecordRepository r=mock(SnackRecordRepository.class);Employee owner=new Employee("Other",true);ReflectionTestUtils.setField(owner,"id",2L);SnackRecord record=new SnackRecord(owner,new Snack("Tea",true),1);when(r.findDetailedById(5L)).thenReturn(Optional.of(record));var service=new SnackTrackerService(mock(EmployeeRepository.class),mock(SnackRepository.class),r);assertThrows(ResponseStatusException.class,()->service.deleteRecord(5L,1L));verify(r,never()).delete(any(SnackRecord.class));}
}
